import { useEffect, useState, type ReactNode } from 'react'
import { BarCI, Figure, XYChart, type BarRow } from '../ui/charts'
import { Card, href, Simulated } from '../ui/kit'

/* eslint-disable @typescript-eslint/no-explicit-any */
type J = any

function useResults() {
  const [d, setD] = useState<Record<string, J> | null>(null)
  const [err, setErr] = useState('')
  useEffect(() => {
    const names = ['real_eval', 'sim_eval', 'realism', 'calibration', 'bedrest']
    Promise.all(names.map((n) => fetch(`${import.meta.env.BASE_URL}results/${n}.json`).then((r) => { if (!r.ok) throw new Error(n); return r.json() })))
      .then((v) => setD(Object.fromEntries(names.map((n, i) => [n, v[i]]))))
      .catch((e) => setErr(String(e)))
  }, [])
  return { d, err }
}

const pct = (v: number | null | undefined) => (v === null || v === undefined || Number.isNaN(v) ? '–' : `${Math.round(v * 100)}%`)
const pts = (v: number | null | undefined) => (v === null || v === undefined || Number.isNaN(v) ? '–' : `${v >= 0 ? '+' : '−'}${Math.abs(Math.round(v * 100))}`)
const ci = (v: number[] | undefined) => (v ? `${Math.round(v[0] * 100)} to ${Math.round(v[1] * 100)}` : '')
const bk = (b: number) => (Number.isInteger(b) ? b.toFixed(1) : String(b)) // result files key budgets as '1.0', '0.25'
const f2 = (v: number | null | undefined, d = 2) => (v === null || v === undefined || Number.isNaN(v) ? '–' : v.toFixed(d))
const SHORT: Record<string, string> = { fixed: 'One threshold for all', zscore: 'Personal, 2-of-3 rule', cusum: 'Personal + CUSUM', mewma: 'Personal + multivariate', fusion: 'Personal, fused' }
const LONG: Record<string, string> = { fixed: 'Fixed threshold, the same for everyone', zscore: 'Personal baseline with a simple 2-of-3-days rule', cusum: 'Personal baseline + CUSUM change detection', mewma: 'Personal baseline + multivariate EWMA', fusion: 'Personal baseline, CUSUM and multivariate fused' }

function Stat({ big, label, sub }: { big: string; label: string; sub?: ReactNode }) {
  return <div className="col" style={{ gap: 2 }}><span className="num" style={{ fontSize: '2rem', fontWeight: 750, lineHeight: 1.1 }}>{big}</span><strong>{label}</strong>{sub && <span className="small muted">{sub}</span>}</div>
}

function MethodTable({ main, methods, deployed, budget }: { main: J; methods: string[]; deployed: string; budget: string }) {
  return (
    <table>
      <thead><tr><th>Method</th><th className="n">Detected</th><th className="n">By luck</th><th className="n">Above luck (95% interval)</th><th className="n">Above luck, versus fixed threshold</th><th className="n">False alerts per person-month</th></tr></thead>
      <tbody>{methods.map((m) => { const s = main[m][budget]; return (
        <tr key={m}><td>{m === deployed ? <strong>{LONG[m]} (Keel)</strong> : LONG[m]}</td><td className="n">{pct(s.detection_rate)}</td><td className="n">{pct(s.chance_detection_rate)}</td><td className="n">{pts(s.net_detection)} ({ci(s.net_detection_ci)})</td><td className="n">{s.net_diff === undefined ? '–' : `${pts(s.net_diff)} (${ci(s.net_diff_ci)})`}</td><td className="n">{f2(s.fa_per_person_month)}{s.fa_per_person_month_ci ? ` (${f2(s.fa_per_person_month_ci[0])} to ${f2(s.fa_per_person_month_ci[1])})` : ''}</td></tr>
      ) })}</tbody>
    </table>
  )
}

function netBars(main: J, methods: string[], deployed: string, budget: string): BarRow[] {
  return methods.map((m) => ({ label: m === deployed ? 'Keel (multivariate)'.replace('multivariate', SHORT[m].replace('Personal + ', '').replace('Personal, ', '')) : SHORT[m], value: main[m][budget].net_detection, lo: main[m][budget].net_detection_ci[0], hi: main[m][budget].net_detection_ci[1], highlight: m === deployed, note: `detected ${pct(main[m][budget].detection_rate)}, by luck ${pct(main[m][budget].chance_detection_rate)}` }))
}

function curves(main: J, budgets: number[], deployed: string) {
  const s = (m: string, label: string, key = 'detection_rate') => ({ label, x: budgets.map((b) => main[m][bk(b)].fa_per_person_month), y: budgets.map((b) => main[m][bk(b)][key]) })
  return [s(deployed, 'Keel'), { ...s(deployed, 'Keel, by luck', 'chance_detection_rate'), dashed: true }, s('fixed', 'Fixed threshold'), { ...s('fixed', 'Fixed, by luck', 'chance_detection_rate'), dashed: true }]
}

function Section({ title, id, children, open = false }: { title: ReactNode; id: string; children: ReactNode; open?: boolean }) {
  return <details className="card" id={id} open={open}><summary><h2 style={{ display: 'inline' }}>{title}</h2></summary><div className="col" style={{ gap: 14, marginTop: 10 }}>{children}</div></details>
}

export function Validation() {
  const { d, err } = useResults()
  if (err) return <Card title="Validation results are not available"><p className="muted">The results files could not be loaded ({err}). Run <code>make validate</code> and rebuild.</p></Card>
  if (!d) return <p role="status">Loading results…</p>
  const R = d.real_eval, S = d.sim_eval, Z = d.realism, B = d.bedrest, C = d.calibration
  const dep: string = R.deployed
  const r1 = R.main[dep]['1.0'], fx1 = R.main.fixed['1.0']
  const s1 = S.main[S.deployed]['1.0']
  const leads: (number | null)[] = R.leads['1.0']
  const leadDays = Array.from({ length: 15 }, (_, i) => 10 - i)
  const leadCounts = leadDays.map((k) => leads.filter((l) => l === k).length)
  const missed = leads.filter((l) => l === null).length
  const fq = R.false_alerts_quiet
  const tr = (k: string) => B.transitions[k]
  const A = R.ablation
  const lr = A.like_for_like_real, lsim = S.like_for_like
  const seeds = Object.values(R.fold_seeds).map((v: any) => v['1.0'].net_detection as number)
  const one = (x: number | null) => (x == null || !(x > 0) ? 'none (it raised no alerts at this tier)' : `about 1 in ${Math.max(2, Math.round(1 / x))}`)
  const co = R.cohort
  // a two-sensor version of Keel's method with model and thresholds from the simulator, applied to real people
  const SM = R.shipped_model, sm1 = SM.all['1.0']
  const DC = R.deployed_config, dA1 = DC.all['1.0'], dA25 = DC.all['0.25'], dH1 = DC.held_out['1.0']
  const a7 = A.rhr_act7, hr = A.rhr, st = A.rhr_steps
  const CS = R.chance_sensitivity['1.0'], OA = R.open_alert_sensitivity['1.0'], W = R.window_sensitivity
  // share of alerts that are a real illness for the import model on the watch maker's resting heart rate
  const vppv = (t: string) => { const tp = Math.max(0, hr[dep][t].net_detection) * 0.97 / 12; return tp / (tp + R.import_model_on_vendor_rhr[t].alerts_per_person_month) }
  const nReal = Z.variability.map((v: J) => v.n_real_people as number)
  const headlineBars = [
    { label: 'Heart rate alone (the import model)', value: hr[dep]['1.0'].net_detection, lo: hr[dep]['1.0'].net_detection_ci[0], hi: hr[dep]['1.0'].net_detection_ci[1], highlight: true, note: `${f2(hr[dep]['1.0'].fa_per_person_month)} false alerts per person-month; the part that does not depend on people moving less` },
    { label: `Two sensors, simulator-set, at ${f2(dA1.fa_per_person_month)} false alerts a month (not comparable)*`, value: dA1.net_detection, lo: dA1.net_detection_ci[0], hi: dA1.net_detection_ci[1], note: `*${f2(dA1.fa_per_person_month)} false alerts per person-month: over its budget of 1.00` },
    { label: 'HR + 7-day activity, real thresholds', value: a7[dep]['1.0'].net_detection, lo: a7[dep]['1.0'].net_detection_ci[0], hi: a7[dep]['1.0'].net_detection_ci[1], note: `${f2(a7[dep]['1.0'].fa_per_person_month)} false alerts per person-month` },
    { label: 'With daily steps', value: st[dep]['1.0'].net_detection, lo: st[dep]['1.0'].net_detection_ci[0], hi: st[dep]['1.0'].net_detection_ci[1], note: `${f2(st[dep]['1.0'].fa_per_person_month)} false alerts per person-month; partly people resting or isolating` },
    { label: 'Fixed threshold, daily steps', value: fx1.net_detection, lo: fx1.net_detection_ci[0], hi: fx1.net_detection_ci[1], note: `${f2(fx1.fa_per_person_month)} false alerts per person-month` },
    { label: 'Fixed threshold, 7-day activity', value: a7.fixed['1.0'].net_detection, lo: a7.fixed['1.0'].net_detection_ci[0], hi: a7.fixed['1.0'].net_detection_ci[1], note: `${f2(a7.fixed['1.0'].fa_per_person_month)} false alerts per person-month` },
    { label: 'Shipped 11-channel model, import channels', value: R.shipped_model.all['1.0'].net_detection, lo: R.shipped_model.all['1.0'].net_detection_ci[0], hi: R.shipped_model.all['1.0'].net_detection_ci[1], note: `${f2(R.shipped_model.all['1.0'].fa_per_person_month)} false alerts per person-month: set for more sensors` },
  ]

  return (
    <>
      <h1>Does it work?</h1>
      <p className="muted">Every number here was produced by a script in the repository. Real data is used wherever it exists; everything else is simulated and labelled. Intervals are 95% bootstrap intervals over people (real data) or missions (simulation), with thresholds held fixed, which makes them somewhat narrower than they should be. Analysis choices such as the metric, the detection window and the detector selection rule were revised during three review rounds, so this is not a pre-planned analysis; the decision log in the repository records each change.</p>

      <section className="card" data-testid="validation-headline">
        <h2>The short version</h2>
        <ul className="list">
          <li><strong>By design:</strong> with no link to Earth, it answers a dangerous reading or a serious symptom at once with one sourced step and an alert to the medical officer and commander. Unit-tested; no clinician has reviewed the thresholds.</li>
          <li><strong>On real illness:</strong> heart rate alone flagged {pct(hr[dep]['1.0'].detection_rate)} of {hr.n_events} episodes against {pct(hr[dep]['1.0'].chance_detection_rate)} by chance ({pts(hr[dep]['1.0'].net_detection)} points, {ci(hr[dep]['1.0'].net_detection_ci)}), at about one false notice a month. No early warning was shown, and most alerts are false. Imported watch data runs on this model.</li>
          <li><strong>Everything else is simulated,</strong> including the tablet's own eleven-channel model (simulated illness {pts(S.by_type['1.0'].illness.net_detection)}, {ci(S.by_type['1.0'].illness.net_detection_ci)}). The tiles and sections below are detail.</li>
        </ul>
        <div className="grid3">
          <Stat big={`${pts(hr[dep]['1.0'].net_detection)} points`} label="above luck on real illness: the import model" sub={<>Overnight heart rate alone, thresholds from other real people (5-fold over people): {pct(hr[dep]['1.0'].detection_rate)} of {hr.n_events} episodes flagged against {pct(hr[dep]['1.0'].chance_detection_rate)} by luck, interval {ci(hr[dep]['1.0'].net_detection_ci)}, at {f2(hr[dep]['1.0'].fa_per_person_month)} false alerts per person-month. Alert tier: {pts(hr[dep]['0.25'].net_detection)} ({ci(hr[dep]['0.25'].net_detection_ci)}). This is what imported data runs on, fitted on all of these people. In the original wider window: {pts(hr.original_window.net_detection)} ({ci(hr.original_window.net_detection_ci)}). On Fitbit's own daily resting heart rate (the kind of value an import carries), for {R.import_model_on_vendor_rhr.n_people} LifeSnaps people without illness labels: {f2(R.import_model_on_vendor_rhr['1.0'].alerts_per_person_month)} alerts per person-month at the notice tier and {f2(R.import_model_on_vendor_rhr['0.25'].alerts_per_person_month)} at the stricter one (budgets 1.00 and 0.25). Caveats: 208 of the 251 people wore Fitbits (other devices did worse, in a small sample with a wide interval), and an import carries the watch maker's own smoothed resting heart rate, not the night-time value the model was calibrated on.</>} />
          <Stat big={`${pts(S.by_type['1.0'].illness.net_detection)} points`} label="above luck for simulated illness: the on-board model" sub={<>All eleven channels, thresholds from simulated training missions, {S.design.test_missions} simulated test missions. Illness, which it sees through physiology and through the simulator's assumed drops in exercise, food intake and sleep when ill: {pts(S.by_type['1.0'].illness.net_detection)} ({ci(S.by_type['1.0'].illness.net_detection_ci)}). All event types together: {pts(s1.net_detection)}, with {pct(s1.detection_rate)} of events flagged against {pct(s1.chance_detection_rate)} by luck, simulation interval {ci(s1.net_detection_ci)} (seed-to-seed variation only, given assumed effect sizes; each cabin CO2 event counts once per crew member). Simulation only, with assumed effect sizes for everything except the illness heart-rate response, which is fitted but fails its own check. Most of it comes from sleep restriction and an exercise outage, whose scripted change is itself an input; illness is {pts(S.by_type['1.0'].illness.net_detection)} ({ci(S.by_type['1.0'].illness.net_detection_ci)}) and cabin CO2 {pts(S.by_type['1.0'].co2.net_detection)} ({ci(S.by_type['1.0'].co2.net_detection_ci)}).</>} />
          <Stat big={`${pts(dA1.net_detection)} points`} label="above luck on real illness: two sensors, simulator thresholds" sub={<>The method fitted only on simulated people, then applied to real people with heart rate and 7-day activity: {pct(dA1.detection_rate)} flagged against {pct(dA1.chance_detection_rate)}, interval {ci(dA1.net_detection_ci)}, but at {f2(dA1.fa_per_person_month)} false alerts per person-month against a budget of 1.00: simulator thresholds run over budget on real people. On the {DC.n_people_held_out} people the simulator's fits did not use ({DC.n_events_held_out} episodes): {pts(dH1.net_detection)} ({ci(dH1.net_detection_ci)}); the hand-set 30% exercise cut was chosen with some of them in view. "7-day activity" is steps here and exercise minutes in the simulator. Alert tier: {pts(dA25.net_detection)} ({ci(dA25.net_detection_ci)}) at {f2(dA25.fa_per_person_month)}. Original wider window: {pts(DC.original_window.net_detection)} ({ci(DC.original_window.net_detection_ci)}).</>} />
        </div>
        <div className="banner strong">
          <strong>What these results do not show.</strong> Useful early warning. At the notice tier an alert started in the ten days before onset or on the day itself for {pct(dA1.by_onset_rate)} of episodes, against {pct(dA1.chance_by_onset_rate)} by luck ({pts(dA1.net_by_onset)}, {ci(dA1.net_by_onset_ci)}); at the alert tier, the one that brings in the medical officer, {pts(dA25.net_by_onset)} ({ci(dA25.net_by_onset_ci)}), about nothing. Those figures are for the two-sensor linking analysis; for heart rate alone, the model imports run on, they are {pts(hr[dep]['1.0'].net_by_onset)} ({ci(hr[dep]['1.0'].net_by_onset_ci)}) and {pts(hr[dep]['0.25'].net_by_onset)} ({ci(hr[dep]['0.25'].net_by_onset_ci)}). Of these four intervals, {[hr[dep]['1.0'].net_by_onset_ci, hr[dep]['0.25'].net_by_onset_ci, dA1.net_by_onset_ci, dA25.net_by_onset_ci].filter((c: number[]) => c[0] > 0).length} exclude zero (an interval whose lower end is just above zero can still show as 0 after rounding). They count the day of onset itself; a luck-adjusted figure for alerts starting strictly before onset was not computed, and onset dates lean on test dates. The notice-tier gain is small and confounded (test dates, isolation after a positive test, lower activity on the day itself), so we do not claim early warning. Most alerts are false: at the in-flight rate of respiratory illness, {one(vppv('0.25'))} alert-tier alerts and {one(vppv('1.0'))} notices would be a real illness for the import model on the watch maker's own resting heart rate, as imports carry it, assuming detection carries over unchanged (not measured) ({one(R.ppv['0.25'].import_model_heart_rate_only)} alert-tier alerts on night-time heart rate), and {one(dA25.share_of_alerts_that_are_real)} for the two-sensor version (a spread across configurations, not an interval; all likely optimistic). <strong>The model file the app ships is calibrated for all eleven channels:</strong> fed only overnight heart rate (and sleep where recorded), as a real import would be, it flagged {pct(sm1.detection_rate)} of episodes ({pts(sm1.net_detection)} above luck) at {f2(sm1.fa_per_person_month)} false alerts per person-month, and at its alert tier it flagged {pct(SM.all['0.25'].detection_rate)} at {f2(SM.all['0.25'].fa_per_person_month)} false alerts per person-month, against a budget of 0.25. Thresholds have to be set for the sensors a person actually has, so imported watch data now runs on a separate heart-rate-only model calibrated on these real people: the "heart rate alone" row below ({pts(hr[dep]['1.0'].net_detection)}, {ci(hr[dep]['1.0'].net_detection_ci)}). {dep === 'zscore' ? 'Keel runs a simple personal rule, and the more complex detectors are not shown to beat it' : 'Keel is not shown to beat a simple personal rule'}, and its lead over one fixed threshold depends on choices we made after seeing data. The data is from people on Earth with consumer watches, mostly with COVID-19. Everything except illness is tested in simulation only.
        </div>
        <p className="small muted">Jump to: <a href="#real" onClick={(e) => { e.preventDefault(); document.getElementById('real')?.setAttribute('open', ''); document.getElementById('real')?.scrollIntoView() }}>real data</a> · <a href="#sim" onClick={(e) => { e.preventDefault(); document.getElementById('sim')?.setAttribute('open', ''); document.getElementById('sim')?.scrollIntoView() }}>simulated missions</a> · <a href="#realism" onClick={(e) => { e.preventDefault(); document.getElementById('realism')?.setAttribute('open', ''); document.getElementById('realism')?.scrollIntoView() }}>simulator realism</a> · <a href="#bedrest" onClick={(e) => { e.preventDefault(); document.getElementById('bedrest')?.setAttribute('open', ''); document.getElementById('bedrest')?.scrollIntoView() }}>NASA bed-rest data</a> · <a href={href('method', 'limits')}>limitations</a></p>
      </section>

      <Figure title="Detection above luck on real illness, notice tier" method="evaluation" script={R.script}
        caption={<>Share of {r1.n_events} real illness episodes flagged, minus the share an alert would hit by luck. Bars show 95% intervals. The first bar is heart rate alone, the model imported data runs on; the second is a two-sensor version of Keel's method with thresholds from the simulator, which runs over its false-alert budget; the next two use thresholds calibrated on other real people (5-fold over people) to one false alert per person-month; the next two are one fixed threshold for everyone; the last is the eleven-channel model the app ships, given only the channels a real import has. Heart rate alone is the figure most likely to carry over to a crew on a fixed exercise schedule.</>}>
        <BarCI rows={headlineBars} max={0.6} pct points ariaLabel="Detection above chance on real illness, by configuration" />
      </Figure>

      <Section id="real" title="1. Real wearable data with dated illness" open>
        <p className="small muted">{R.data}. Indicators available: {R.indicators.toLowerCase()}. No HRV, oxygen or temperature exists in this data.</p>
        <div className="tablewrap"><table>
          <thead><tr><th>Who is in the test</th><th className="n">Recordings</th></tr></thead>
          <tbody>
            <tr><td>Downloaded (all 120 of phase 1; all 84 positives and 120 others of phase 2)</td><td className="n">{co.n_downloaded}</td></tr>
            <tr><td>Left out: fewer than 28 nights with a usable resting heart rate</td><td className="n">−{co.excluded_under_28_nights}</td></tr>
            <tr><td><strong>Analysed</strong> ({Object.entries(co.by_device).map(([k, v]) => `${v} ${k}`).join(', ')})</td><td className="n"><strong>{co.n_people}</strong></td></tr>
            <tr><td>… with a dated illness episode inside their recording ({co.n_events} episodes: {co.by_kind.covid_symptom} COVID-19 with a symptom date, {co.by_kind.covid_test_only} with a test date only, {co.by_kind.other_illness} other illness)</td><td className="n">{co.n_with_event}</td></tr>
            {Object.entries(co.quiet_people).map(([k, v]) => <tr key={k}><td>… without one: {k}</td><td className="n">{v as number}</td></tr>)}
          </tbody>
        </table></div>
        <p className="small muted">Left out for too few nights: {co.excluded_with_illness} of the {co.excluded_under_28_nights} had a dated illness ({co.excluded_with_illness_by_device?.AppleWatch ?? 0} of them Apple Watch users, whose overnight samples are sparse in this release), so the result leans on Fitbit wearers ({co.events_by_device.Fitbit} of {co.n_events} episodes).</p>
        <p className="small muted">{co.person_days.toLocaleString()} person-days; {Math.round(co.quiet_person_months_scored)} person-months of scored quiet time. {co.sampling_note} Every episode counts for every method: an episode Keel could not score (no baseline yet) is a miss.</p>

        <div className="grid2">
          <Figure title="Keel's detector against simpler ones, real data" method="evaluation" script={R.script}
            caption={<>Heart rate and daily steps, thresholds from other real people, one false alert per person-month. <strong>The four personal-baseline methods cannot be told apart:</strong> {dep === 'zscore' ? <>Keel now runs the simple two-of-three-days rule itself; the multivariate EWMA against it is {pts(R.main.mewma['1.0'].net_diff_vs_zscore)} ({ci(R.main.mewma['1.0'].net_diff_vs_zscore_ci)}).</> : <>Keel's detector against the simple two-of-three-days rule is {pts(r1.net_diff_vs_zscore)} ({ci(r1.net_diff_vs_zscore_ci)}).</>} Against one fixed threshold Keel leads by {pts(r1.net_diff)} ({ci(r1.net_diff_ci)}) in the −10..+4 day window, by {pts(W['-14..+7'].net_diff_vs_fixed)} ({ci(W['-14..+7'].net_diff_vs_fixed_ci)}) in the original −14..+7 window, and by {pts(OA[dep].net_diff)} ({ci(OA[dep].net_diff_ci)}) if an alert that is already open in the window also counts. The simple rule's lead over the fixed threshold is {pts(R.main.zscore['1.0'].net_diff)} ({ci(R.main.zscore['1.0'].net_diff_ci)}). Four detectors, two tiers and a window chosen after seeing data were compared with no correction for multiple looks, and the like-for-like contrast of a personal against a population baseline (the same 2-of-3 rule) is {pts(R.main.zscore['1.0'].net_diff)} ({ci(R.main.zscore['1.0'].net_diff_ci)}) at the notice tier but {pts(R.main.zscore['0.25'].net_diff)} ({ci(R.main.zscore['0.25'].net_diff_ci)}) at the alert tier: mixed evidence, with no correction for multiple comparisons. {dep === 'zscore' ? 'The app runs the simple rule because, once a sign error in the multivariate statistic was corrected (review round 15), the multivariate detector no longer led it by the pre-set margin on the simulated training missions; the real data had no vote.' : 'We did not switch the app to the simple rule after seeing these results: that would mean choosing on the test data. It would be a reasonable choice for a flight version.'}</>}
            table={<MethodTable main={R.main} methods={R.methods} deployed={dep} budget="1.0" />}>
            <BarCI rows={netBars(R.main, R.methods, dep, '1.0')} max={0.6} pct points ariaLabel="Detection above chance by method on real data" />
          </Figure>
          <Figure title="Detection against false alerts, real data" method="evaluation" script={R.script}
            caption={<>Each point is a false-alert budget ({R.budgets.join(', ')} per person-month), placed at the rate actually measured on held-out people. Dashed lines show how often an alert falls in the window by luck. The gap between a solid line and its dashed line is the real signal. At loose budgets alerts are open so often that fewer new ones start inside the window, so the curves flatten.</>}
            table={<MethodTable main={R.main} methods={R.methods} deployed={dep} budget="0.25" />}>
            <XYChart series={curves(R.main, R.budgets, dep)} xLabel="False alerts per person-month (measured)" yLabel="Episodes flagged" yPct yMin={0} yMax={1} ariaLabel="Detection rate against false alert rate on real data" />
          </Figure>
        </div>
        <Card title="How much depends on how luck is measured">
          <p className="small">Luck is estimated by placing pretend illness dates on quiet days and scoring them like real ones. Pretend dates handle missing data the same way as real ones (they carry the person's quiet-time gaps, not the extra unworn days illness brings) and are weighted to the device mix of the real episodes: luck {pct(CS.device_weighted.chance_detection_rate)}, gap {pts(CS.device_weighted.net_detection)}. Matched to how far into the recording real onsets fall (a young baseline is noisier): {pct(CS.matched_on_days_since_recording_start.chance_detection_rate)}, gap {pts(CS.matched_on_days_since_recording_start.net_detection)}. Using only people who had an episode: {pct(CS.only_people_who_had_an_episode.chance_detection_rate)}, gap {pts(CS.only_people_who_had_an_episode.net_detection)}. Requiring a score on every day of a pretend window, as our earlier analysis did: {pct(CS.windows_with_a_score_every_day.chance_detection_rate)}, gap {pts(CS.windows_with_a_score_every_day.net_detection)}. As a share of what luck leaves to be found, the gap is {pct(r1.net_rescaled)}.</p>
          <p className="small"><strong>What this cannot fix.</strong> {R.chance_note}</p>
          <p className="figcap"><a href={href('method', 'evaluation')}>How this was measured</a> · <code>{R.script}</code></p>
        </Card>

        <div className="grid2">
          <Figure title="When the alert came, relative to symptom onset" method="evaluation" script={R.script}
            caption={<>Keel at one false alert per person-month. Left of the line, the alert started before symptoms; right of it, after. {missed} of {leads.length} episodes had no alert in the window. The cluster just after onset is the real response; alerts a week before onset are mostly coincidence.</>}>
            <XYChart series={[{ label: 'Episodes', x: leadDays.map((k) => -k), y: leadCounts }]} xLabel="Days from symptom onset to alert start (negative = alert first)" yLabel="Episodes" ariaLabel="Histogram of alert timing relative to symptom onset" xDecimals={0} yDecimals={0} yMin={0} step vline={{ x: 0, label: 'Onset' }} />
          </Figure>
          <Figure title="What real illness looks like in resting heart rate" method="simulator" script={R.script}
            caption={<>Mean change from each person's own earlier level, {R.event_aligned_rhr.n_events} dated episodes, with a 95% band. The rise is small before symptoms and peaks a day or two after onset. Night-to-night variation is about {f2(Z.variability[0].real_sd_median, 1)} bpm, so a single person's rise is hard to see.</>}>
            <XYChart series={[{ label: 'Mean change', x: R.event_aligned_rhr.rel_day, y: R.event_aligned_rhr.mean, lo: R.event_aligned_rhr.lo, hi: R.event_aligned_rhr.hi }]} xLabel="Days from symptom onset" yLabel="Resting heart rate change, bpm" ariaLabel="Event-aligned resting heart rate around illness onset" xDecimals={0} yDecimals={1} vline={{ x: 0, label: 'Onset' }} />
          </Figure>
        </div>

        <Card title="What an alert is worth">
          <p className="small">ISS crews report about one episode of upper-respiratory symptoms per person-year. At that rate, and with the detection above luck measured here, {one(R.ppv['0.25'].share_of_alerts_that_are_real)} alert-tier alerts and {one(R.ppv['1.0'].share_of_alerts_that_are_real)} notices would be attributable to such an illness with daily steps and thresholds from real people; {one(R.ppv['0.25'].with_7_day_activity)} and {one(R.ppv['1.0'].with_7_day_activity)} with the 7-day activity average; and {one(dA25.share_of_alerts_that_are_real)} and {one(dA1.share_of_alerts_that_are_real)} with thresholds from the simulator, which run over budget; on the watch maker's own resting heart rate, where the import model's false-alert rates are higher (assuming detection carries over unchanged, which was not measured), {one(Math.max(0, hr[dep]['0.25'].net_detection) * 0.97 / 12 / (Math.max(0, hr[dep]['0.25'].net_detection) * 0.97 / 12 + R.import_model_on_vendor_rhr['0.25'].alerts_per_person_month))} and {one(Math.max(0, hr[dep]['1.0'].net_detection) * 0.97 / 12 / (Math.max(0, hr[dep]['1.0'].net_detection) * 0.97 / 12 + R.import_model_on_vendor_rhr['1.0'].alerts_per_person_month))}; and {one(R.ppv['0.25'].import_model_heart_rate_only)} and {one(R.ppv['1.0'].import_model_heart_rate_only)} for the heart-rate-only model imports run on. These are likely optimistic estimates of the share that is a respiratory illness (they assume one true alert per illness and false-alert rates measured on Earth): the sensitivity comes from mostly symptomatic COVID-19, in-flight colds are milder, and full-sensor thresholds running over budget (section 3) would lower them further. Alerts for the other conditions Keel watches for are not counted here; they cannot be measured on real data. For imported watch data the closest figures are the heart-rate-only ones on the watch maker's resting heart rate; for the on-board model, the simulator-threshold ones. This is why a notice asks for a look, not for the medical officer.</p>
          <p className="figcap">Assumes 0.97 illnesses per person-year (upper-respiratory symptoms on the ISS, source 52b) and the detection above luck measured on real data. <a href={href('method', 'evaluation')}>How this was measured</a> · <code>{R.script}</code></p>
        </Card>

        <Card title="False alerts over long quiet periods">
          <p className="small">People with no dated illness in their recording ({fq['1.0'].n_people} people, {Math.round(fq['1.0'].quiet_person_months)} scored person-months; many were never confirmed healthy, so some alerts may be real). Notice tier: {f2(fq['1.0'].fa_per_person_month)} false alerts per person-month (interval {f2(fq['1.0'].fa_per_person_month_ci[0])} to {f2(fq['1.0'].fa_per_person_month_ci[1])}), with an alert open on {pct(fq['1.0'].quiet_days_in_alert_frac)} of quiet days. Alert tier: {f2(fq['0.25'].fa_per_person_month)} per person-month, open on {pct(fq['0.25'].quiet_days_in_alert_frac)} of days; {pct(fq['0.25'].share_of_people_with_zero)} of people never saw one. The noisiest fifth of people produced {pct(fq['0.25'].share_of_alerts_from_top_fifth)} of alert-tier false alerts, which is what pure chance would give ({pct(fq['0.25'].top_fifth_if_constant_rate)}). Within this group we found no clear sign of individuals who are systematically noisier (no formal test). Between groups (computed over all people, not only this group) the rate does differ: non-Fitbit devices {f2(R.breakdown['1.0'].device_other.fa_per_person_month)} per person-month ({f2(R.breakdown['1.0'].device_other.fa_per_person_month_ci[0])} to {f2(R.breakdown['1.0'].device_other.fa_per_person_month_ci[1])}) against {f2(R.breakdown['1.0'].device_Fitbit.fa_per_person_month)} for Fitbit, and {f2(R.false_alerts_by_group.no_reported_illness['1.0'].fa_per_person_month)} for phase 1 people who reported no illness against {f2(R.false_alerts_by_group.non_positive['1.0'].fa_per_person_month)} for phase 2 people not in the positives table.</p>
          <p className="small">Not counted anywhere: alerts starting 11 to 21 days before an episode or 5 to 28 days after it fall outside the detection window but inside the exclusion zone. There were {R.uncounted_alerts_near_episodes['1.0'].alerts} at the notice tier ({f2(R.uncounted_alerts_near_episodes['1.0'].per_episode, 1)} per episode) and {R.uncounted_alerts_near_episodes['0.25'].alerts} at the alert tier, so the false-alert rates understate the burden for people who were ill.</p>
          <BarCI rows={fq['1.0'].hist_edges.map((e: string, i: number) => ({ label: `${e} per month`, value: fq['1.0'].per_person_rate_hist[i] }))} decimals={0} unit="people" ariaLabel="People by their personal false alert rate at the notice tier" />
          <p className="figcap">People with at least 30 scored quiet days ({fq['1.0'].n_people_30_days}), by their own false-alert rate at the notice tier. <a href={href('method', 'evaluation')}>How this was measured</a> · <code>{R.script}</code></p>
        </Card>

        <Card title="Which indicators and components earn their place (real data)">
          <div className="tablewrap"><table>
            <thead><tr><th>Indicators</th><th className="n">Notice tier: flagged, luck</th><th className="n">Above luck (interval)</th><th className="n">Alert tier: flagged, luck</th><th className="n">Above luck (interval)</th></tr></thead>
            <tbody>
              {['rhr', 'rhr_steps', 'rhr_act7', 'rhr_steps_adjusted', 'rhr_rhrday_steps'].filter((k) => A[k]).map((k) => { const v = A[k][dep]['1.0'], q = A[k][dep]['0.25']; return <tr key={k}><td>{A[k].label}{k === 'rhr_act7' ? ' (the activity feature the app uses)' : ''}</td><td className="n">{pct(v.detection_rate)}, {pct(v.chance_detection_rate)}</td><td className="n">{pts(v.net_detection)} ({ci(v.net_detection_ci)})</td><td className="n">{pct(q.detection_rate)}, {pct(q.chance_detection_rate)}</td><td className="n">{pts(q.net_detection)} ({ci(q.net_detection_ci)})</td></tr> })}
              {A.sleep_subset && <tr><td>Adding sleep duration, in the {A.sleep_subset.n_people} people who have it: without → with</td><td className="n">{pct(A.sleep_subset.without_sleep.detection_rate)} → {pct(A.sleep_subset.with_sleep.detection_rate)}</td><td className="n">–</td><td className="n">–</td><td className="n">–</td></tr>}
            </tbody>
          </table></div>
          <ul className="list small">
            <li><strong>Steps add much of the signal, and that is a caution.</strong> Heart rate alone is {pts(A.rhr[dep]['1.0'].net_detection)} points above luck; with steps, {pts(A.rhr_steps[dep]['1.0'].net_detection)}. Median daily steps fell from {Math.round(R.steps_drop.baseline_median).toLocaleString()} to {Math.round(R.steps_drop.onset_to_day4_median).toLocaleString()} in the five days from onset ({R.steps_drop.n_episodes} episodes): people rest, or isolate after a positive test. A crew on a fixed exercise schedule may not show that, and because the data owners shifted every person's dates we cannot separate it from lockdowns.</li>
            <li><strong>At the alert tier the choice of activity feature matters.</strong> With daily steps Keel is {pts(A.rhr_steps[dep]['0.25'].net_detection)} above luck; with the smoother 7-day average the app uses, {pts(A.rhr_act7[dep]['0.25'].net_detection)}, and its lead over a fixed threshold on the same sensors is {pts(a7[dep]['0.25'].net_diff)} ({ci(a7[dep]['0.25'].net_diff_ci)}). At the notice tier that lead is {pts(a7[dep]['1.0'].net_diff)} ({ci(a7[dep]['1.0'].net_diff_ci)}).</li>
            <li><strong>Adjusting heart rate for the previous day's activity does not help</strong> ({pts(A.rhr_steps_adjusted[dep]['1.0'].net_detection)} against {pts(A.rhr_steps[dep]['1.0'].net_detection)}), so the app leaves it off.</li>
            <li><strong>Sleep is undecided.</strong> Too few people have sleep data.</li>
            <li><strong>Device may matter</strong> (no interval for the difference). Fitbit: {pct(R.breakdown['1.0'].device_Fitbit.detection_rate)} flagged ({pts(R.breakdown['1.0'].device_Fitbit.net_detection)} above luck, {R.breakdown['1.0'].device_Fitbit.n_events} episodes). Non-Fitbit devices: {pct(R.breakdown['1.0'].device_other.detection_rate)} ({pts(R.breakdown['1.0'].device_other.net_detection)}, {R.breakdown['1.0'].device_other.n_events} episodes, all Apple Watch); their overnight heart-rate samples are sparse in this release.</li>
            <li><strong>People who reported no illness in phase 1</strong> saw {f2(R.false_alerts_by_group.no_reported_illness['1.0'].fa_per_person_month)} false alerts per person-month at the notice tier (interval {f2(R.false_alerts_by_group.no_reported_illness['1.0'].fa_per_person_month_ci[0])} to {f2(R.false_alerts_by_group.no_reported_illness['1.0'].fa_per_person_month_ci[1])}).</li>
            <li><strong>It holds across cohorts.</strong> Trained on phase 1 and tested on phase 2: {pct(R.cross_phase.train_phase1_test_phase2['1.0'].detection_rate)} flagged, {pts(R.cross_phase.train_phase1_test_phase2['1.0'].net_detection)} above luck, {f2(R.cross_phase.train_phase1_test_phase2['1.0'].fa_per_person_month)} false alerts per person-month. The reverse: {pct(R.cross_phase.train_phase2_test_phase1['1.0'].detection_rate)}, {pts(R.cross_phase.train_phase2_test_phase1['1.0'].net_detection)}, {f2(R.cross_phase.train_phase2_test_phase1['1.0'].fa_per_person_month)}. Five different fold splits gave {pts(Math.min(...seeds))} to {pts(Math.max(...seeds))} above luck.</li>
            <li><strong>Retrospective and prospective phase 2 cases</strong> (the prospective ones were enrolled under the original study's own alerting): {pts(R.breakdown['1.0'].phase2_retrospective.net_detection)} and {pts(R.breakdown['1.0'].phase2_prospective.net_detection)} above luck.</li>
            <li><strong>The window.</strong> {Object.entries(R.window_sensitivity).map(([k, v]: [string, any]) => `${k} days: ${pct(v.detection_rate)} flagged, ${pct(v.chance)} by luck, gap ${pts(v.net)} (${ci(v.net_ci)})`).join('; ')}. The window was narrowed from −14..+7 to −10..+4 while the real-data evaluation was being written. The commit history cannot show that this came before the first run, and −10..+4 has the largest gap of the four, so treat the original window as the conservative figure.</li>
            <li><strong>Published comparison.</strong> The dataset's authors reported {pct(R.published.presymptomatic_detection)} of 32 cases detectable before symptoms with about {R.published.false_alarms_per_month_healthy} alarms per month, using hourly data and their own algorithm on phase 1. We did not reproduce early detection with daily features.</li>
          </ul>
        </Card>
      </Section>

      <Section id="sim" title={<>2. Simulated missions <Simulated /></>}>
        <p className="small muted">{S.design.test_missions} test missions of {S.design.crew} crew and {S.design.flight_days} days, {S.design.n_test_events} person-events of six kinds; model and thresholds fitted on {S.design.train_missions} separate training missions. The simulator's day-to-day noise, its correlations between indicators and its illness response are fitted to real data (section 3). All other effect sizes are assumptions, so these numbers show how the method behaves, not how well it would work in flight.</p>
        <div className="grid2">
          <Figure title="Detection above luck, simulated missions" method="evaluation" script={S.script} caption={<>Full indicator set, one false alert per person-month. Keel flagged {pct(s1.detection_rate)} against {pct(s1.chance_detection_rate)} by luck. Intervals are over missions, because crewmates share a cabin. Keel's lead over the fixed threshold here is {pts(s1.net_diff)} ({ci(s1.net_diff_ci)}). The detector Keel runs was picked on the training missions by a margin rule; the candidates are within noise of each other on these test missions, so the choice is best read as arbitrary among equals.</>} table={<MethodTable main={S.main} methods={S.methods} deployed={S.deployed} budget="1.0" />}>
            <BarCI rows={netBars(S.main, S.methods, S.deployed, '1.0')} max={0.6} pct points ariaLabel="Detection above chance by method on simulated missions" />
          </Figure>
          <Figure title="Detection against false alerts, simulated missions" method="evaluation" script={S.script} caption="Same reading as the real-data chart. For the personal detectors, thresholds trained on other missions stay close to their budget on test missions." table={<MethodTable main={S.main} methods={S.methods} deployed={S.deployed} budget="0.25" />}>
            <XYChart series={curves(S.main, S.budgets, S.deployed)} xLabel="False alerts per person-month (measured)" yLabel="Events flagged" yPct yMin={0} yMax={1} ariaLabel="Detection rate against false alert rate on simulated missions" />
          </Figure>
        </div>
        <Card title="By event type and size">
          <div className="tablewrap"><table>
            <thead><tr><th>Event</th>{S.dose.illness.sizes.map((z: number) => <th key={z} className="n">size {z}×</th>)}<th className="n">Above luck, mixed sizes (interval)</th><th className="n">Alert before the event began</th><th className="n">Typical delay after it began</th></tr></thead>
            <tbody>{Object.entries(S.dose).map(([k, v]: [string, any]) => <tr key={k}><td>{v.label}</td>{v['1.0'].map((x: number, i: number) => <td key={i} className="n">{pct(x)}</td>)}<td className="n">{pts(S.by_type['1.0'][k].net_detection)} ({ci(S.by_type['1.0'][k].net_detection_ci)})</td><td className="n">{pct(S.by_type['1.0'][k].share_alert_before_onset)}</td><td className="n">{S.by_type['1.0'][k].median_delay_days === null ? '–' : `${f2(S.by_type['1.0'][k].median_delay_days, 0)} d`}</td></tr>)}</tbody>
          </table></div>
          <p className="figcap">Raw share flagged at the notice tier by event size, before subtracting luck, which is about {pct(s1.chance_detection_rate)} at this budget ({S.dose.illness.n[0]} events per cell, so each figure is good to about ±10 points; 1× is the average size, and for illness that is the average real heart-rate response). "Above luck" is from the main test missions, where sizes vary as in the fitted spread ({Object.values(S.by_type['1.0']).map((v: any) => v.n).join(', ')} person-events per row in table order; a cabin CO2 event counts once per crew member). <strong>For illness and low mood the interval includes zero, and sleep restriction and an exercise outage are easy because the scripted variable is itself something Keel reads.</strong> The overall simulated figure therefore depends on the mix of events. "Alert before the event began" is mostly luck and is the simulated counterpart of the real-data finding that there is no early warning. A slow cabin CO2 rise is the hardest for the personal detector, which is why Keel also watches the cabin sensor directly. <a href={href('method', 'simulator')}>How events are simulated</a> · <code>{S.script}</code></p>
        </Card>
        <div className="grid2">
          <Figure title="Missing data" method="evaluation" script={S.script} caption="Detection when the wearable is not worn or check-ins are skipped. Thresholds are not re-tuned, so false alerts fall along with detection; the table shows both."
            table={<table><thead><tr><th>Condition</th><th className="n">Flagged</th><th className="n">False alerts / person-month</th></tr></thead><tbody>{S.missing.map((m: J) => <tr key={m.label}><td>{m.label}</td><td className="n">{pct(m['1.0'].detection_rate)}</td><td className="n">{f2(m['1.0'].fa_per_person_month)}</td></tr>)}</tbody></table>}>
            <BarCI rows={S.missing.map((m: J, i: number) => ({ label: m.label, value: m['1.0'].detection_rate, lo: m['1.0'].detection_rate_ci[0], hi: m['1.0'].detection_rate_ci[1], highlight: i === 0, note: `${f2(m['1.0'].fa_per_person_month)} false alerts per person-month` }))} max={1} pct ariaLabel="Detection rate under missing data" />
          </Figure>
          <Figure title="Losing a sensor" method="evaluation" script={S.script} caption="Detection with one input removed for the whole mission. Fewer inputs also mean fewer false alerts (see the table), so part of each drop is the detector simply saying less."
            table={<table><thead><tr><th>Condition</th><th className="n">Flagged</th><th className="n">False alerts / person-month</th></tr></thead><tbody>{S.dropout.map((m: J) => <tr key={m.label}><td>{m.label}</td><td className="n">{pct(m['1.0'].detection_rate)}</td><td className="n">{f2(m['1.0'].fa_per_person_month)}</td></tr>)}</tbody></table>}>
            <BarCI rows={S.dropout.map((m: J, i: number) => ({ label: m.label, value: m['1.0'].detection_rate, lo: m['1.0'].detection_rate_ci[0], hi: m['1.0'].detection_rate_ci[1], highlight: i === 0, note: `${f2(m['1.0'].fa_per_person_month)} false alerts per person-month` }))} max={1} pct ariaLabel="Detection rate with one sensor removed" />
          </Figure>
        </div>
        <Card title="Which design choices earn their place (simulated)">
          <div className="tablewrap"><table>
            <thead><tr><th>Variant</th><th className="n">Flagged</th><th className="n">Interval</th><th className="n">False alerts / person-month</th><th className="n">… in the first 30 flight days</th></tr></thead>
            <tbody>{S.ablation.map((a: J, i: number) => <tr key={a.label}><td>{i === 0 ? <strong>{a.label}</strong> : a.label}</td><td className="n">{pct(a['1.0'].detection_rate)}</td><td className="n">{ci(a['1.0'].detection_rate_ci)}%</td><td className="n">{f2(a['1.0'].fa_per_person_month)}</td><td className="n">{f2(a.first_30_flight_days_fa_per_person_month)}</td></tr>)}</tbody>
          </table></div>
          <ul className="list small">
            <li><strong>Mission-phase handling halves alerts after launch</strong> (all alerts in the first 30 flight days, whatever their cause), from {f2(S.ablation[1].first_30_flight_days_fa_per_person_month)} to {f2(S.ablation[0].first_30_flight_days_fa_per_person_month)} per person-month in the first 30 flight days. It does not depend on knowing the expected shift: told to expect no shift at all it still gives {f2(S.ablation[2].first_30_flight_days_fa_per_person_month)}. The benefit comes from restarting the baseline and widening the band.</li>
            <li><strong>No measured cost for events right after launch.</strong> Events that begin in flight days 3 to 25 are flagged {pct(S.early_events['phase-aware'].detection_rate)} with phase handling and {pct(S.early_events.naive.detection_rate)} without, but a naive baseline also alerts on the adaptation itself: pretend events on the same flight days of event-free missions are hit {pct(S.early_events['phase-aware'].chance_detection_rate)} and {pct(S.early_events.naive.chance_detection_rate)} of the time. Above luck: {pts(S.early_events['phase-aware'].net_detection)} ({ci(S.early_events['phase-aware'].net_detection_ci)}) with phase handling, {pts(S.early_events.naive.net_detection)} ({ci(S.early_events.naive.net_detection_ci)}) without. (An earlier version took luck from late flight and wrongly reported a cost.)</li>
            <li><strong>Check-ins seem to matter</strong> (raw rates, not above luck, and several scripted events act through check-in answers): wearable-only detection is {pct(S.ablation[S.ablation.length - 1]['1.0'].detection_rate)}.</li>
            <li><strong>Some defaults are not optimal.</strong> Faster smoothing did better here. We kept the values chosen before testing rather than tune on the test missions.</li>
            <li><strong>Quiet missions.</strong> In {Math.round(S.quiet['1.0'].quiet_person_months)} person-months with no event at all: {f2(S.quiet['1.0'].fa_per_person_month)} false alerts per person-month at the notice tier (budget 1.00) and {f2(S.quiet['0.25'].fa_per_person_month)} at the alert tier (budget 0.25).</li>
            <li><strong>These tables show raw flagged rates.</strong> Luck is about {pct(s1.chance_detection_rate)} at the notice tier, so a row at 50% is barely above chance.</li>
          </ul>
          <p className="figcap"><a href={href('method', 'evaluation')}>How this was measured</a> · <code>{S.script}</code></p>
        </Card>
      </Section>

      <Section id="realism" title="3. Is the simulator realistic?">
        <p className="small muted">{Z.note} Pass marks: {Z.criteria.variability}; {Z.criteria.carry_over}; correlation {Z.criteria.correlation}; {Z.criteria.illness}; {Z.criteria.transfer}.</p>
        <Card title="Two checks that tie the simulator to reality">
          <p><strong>Like for like.</strong> Simulated people on the ground, illness only, using the two channels the real illness data has (resting heart rate and 7-day activity): Keel flags {pct(lsim['1.0'].detection_rate)}, {pts(lsim['1.0'].net_detection)} points above luck (interval {ci(lsim['1.0'].net_detection_ci)}). The same analysis on real symptom-dated episodes of people not used by the simulator's fits ({lr['1.0'].n_events} episodes): {pct(lr['1.0'].detection_rate)}, {pts(lr['1.0'].net_detection)} above luck (interval {ci(lr['1.0'].net_detection_ci)}). At the alert tier: {pts(lsim['0.25'].net_detection)} simulated against {pts(lr['0.25'].net_detection)} real. <strong>On these channels simulated illness is harder to detect than real illness,</strong> possibly because the simulated crew cuts exercise by 30% when ill while real people's steps roughly halve, and because the simulated heart-rate rise is smaller; no run isolates either cause. The simulator's spread of illness sizes also counts errors in reported onset dates as real variation, which makes more simulated illnesses near-silent. That 30% was set by hand with this comparison in view, so this check is not independent of the simulator's design. The simulated heart-rate response itself is {Z.illness.pass ? 'within' : 'outside'} our 25% pass mark: {f2(Z.illness.peak_window_mean.sim, 1)} bpm over the four days from onset against {f2(Z.illness.peak_window_mean.real, 1)} real.</p>
          <p><strong>Threshold transfer.</strong> Alert thresholds calibrated only on simulated people, applied unchanged to {Z.transfer.n_real_people} real people with no dated illness (the half the simulator was not fitted on), gave {f2(Z.transfer.budgets['1.0'].real_fa_per_person_month)} false alerts per person-month against a budget of 1.00 ({Z.transfer.budgets['1.0'].pass ? 'pass' : 'fail'}) and {f2(Z.transfer.budgets['0.25'].real_fa_per_person_month)} against 0.25 ({Z.transfer.budgets['0.25'].pass ? 'pass' : 'fail'}). Real data produces more false alerts than the simulator expects (night-to-night spread is similar; tails and the steps-versus-exercise mismatch are likelier causes).</p>
          {Z.transfer_wide && <p><strong>The same test with five indicators</strong> ({Z.transfer_wide.indicators}) on {Z.transfer_wide.n_real_people} LifeSnaps people ({Math.round(Z.transfer_wide.budgets['1.0'].real_person_months)} person-months; no illness labels, so some alerts may be real): {f2(Z.transfer_wide.budgets['1.0'].real_alerts_per_person_month)} alerts per person-month against a budget of 1.00 ({Z.transfer_wide.budgets['1.0'].pass ? 'pass' : 'fail'}) and {f2(Z.transfer_wide.budgets['0.25'].real_alerts_per_person_month)} against 0.25 ({Z.transfer_wide.budgets['0.25'].pass ? 'pass' : 'fail'}). <strong>The wider the sensor set, the worse simulated thresholds transfer.</strong> The thresholds the app uses for the full set would need recalibrating on real crew data before anyone relied on the budget.</p>}
          <p className="figcap"><code>{S.script}</code>, <code>{R.script}</code>, <code>{Z.script}</code></p>
        </Card>
        <Card title="Day-to-day behaviour: simulated crew against real people">
          <div className="tablewrap"><table>
            <thead><tr><th>Indicator</th><th className="n">Real variability</th><th className="n">Simulated</th><th>Within 25%?</th><th className="n">Carry-over, real / simulated</th><th>Within 0.15?</th></tr></thead>
            <tbody>{Z.variability.map((v: J) => <tr key={v.id}><td>{v.label} ({v.unit})</td><td className="n">{f2(v.real_sd_median)} ({f2(v.real_sd_iqr[0])} to {f2(v.real_sd_iqr[1])})</td><td className="n">{f2(v.sim_sd_median)} ({f2(v.sim_sd_iqr[0])} to {f2(v.sim_sd_iqr[1])})</td><td>{v.sd_pass ? 'Pass' : 'Fail'}</td><td className="n">{f2(v.real_ar1_median)} / {f2(v.sim_ar1_median)}</td><td>{v.ar1_pass ? 'Pass' : 'Fail'}</td></tr>)}</tbody>
          </table></div>
          <div className="tablewrap"><table>
            <thead><tr><th>Link between two indicators within a person</th><th className="n">Real</th><th className="n">Simulated</th><th>Within 0.15?</th></tr></thead>
            <tbody>{Z.correlation.map((c: J) => <tr key={c.label}><td>{c.label}</td><td className="n">{f2(c.real_median)} ({c.n_real_people} people)</td><td className="n">{f2(c.sim_median)}</td><td>{c.pass ? 'Pass' : 'Fail'}</td></tr>)}</tbody>
          </table></div>
          <p className="figcap">Variability is the standard deviation of one person's daily values around their own slow trend (median across people, with the middle half in brackets). Carry-over is how much of today's deviation remains tomorrow. Real figures come from the validation half ({Math.min(...nReal)} to {Math.max(...nReal)} people per row). The simulator is tuned on the other half, so agreement shows the tuning carried over, not that the simulator is right in ways we did not measure. <a href={href('method', 'simulator')}>How the simulator is built</a> · <code>{Z.script}</code></p>
        </Card>
        <div className="grid2">
          <Figure title="Illness response: real against simulated" method="simulator" script={Z.script}
            caption={<>Mean resting heart rate change around symptom onset. Real: {Z.illness.real.n} episodes from the validation half. Simulated: {Z.illness.sim.n} episodes with the real spread of sizes, including the three in ten that show no rise. Over the four days from onset the mean rise is {f2(Z.illness.peak_window_mean.real, 1)} bpm real and {f2(Z.illness.peak_window_mean.sim, 1)} simulated; the gap's 95% interval is {f2(Z.illness.real_minus_sim_ci[0], 1)} to {f2(Z.illness.real_minus_sim_ci[1], 1)} bpm, but that interval leaves out the uncertainty in the simulator's own fit from the other half, whose rise was smaller, so much of the gap may be split-half noise.</>}>
            <XYChart series={[{ label: 'Real', x: Z.illness.rel_day, y: Z.illness.real.mean, lo: Z.illness.real.lo, hi: Z.illness.real.hi }, { label: 'Simulated', x: Z.illness.rel_day, y: Z.illness.sim.mean, lo: Z.illness.sim.lo, hi: Z.illness.sim.hi }]} xLabel="Days from symptom onset" yLabel="Change, bpm" xDecimals={0} yDecimals={1} vline={{ x: 0, label: 'Onset' }} ariaLabel="Event-aligned resting heart rate, real versus simulated" />
          </Figure>
          <Figure title="Published in-flight values" method="simulator" script={Z.script} caption={<>Fitted illness response: mean peak {f2(C.illness.peak_bpm, 1)} bpm, from {C.illness.n_events} episodes whose individual responses range from none (lower quartile {f2(C.illness.per_episode_quartiles[0], 1)}) to {f2(C.illness.per_episode_quartiles[2], 1)} bpm (upper quartile). Reference numbers refer to <a href={href('method', 'sources')}>the source list</a>.</>}>
            <div className="tablewrap"><table>
              <thead><tr><th>Quantity</th><th className="n">Published</th><th className="n">Simulated</th><th>Kind of check</th></tr></thead>
              <tbody>{Z.anchors.map((a: J) => <tr key={a.what}><td>{a.what} <span className="muted">[{a.ref}]</span></td><td className="n">{a.published === null ? 'about 1.9' : `${a.published} ${a.unit}`}</td><td className="n">{f2(a.simulated, a.unit === 'h' ? 2 : 1)} {a.unit}</td><td className="small">{a.input ? 'Input (shows only that the code does what it says)' : 'Independent check; the simulator is off'}</td></tr>)}</tbody>
            </table></div>
          </Figure>
        </div>
      </Section>

      <Section id="bedrest" title="4. Gravity transitions on real NASA analog data">
        <p className="small muted">{B.data}. {B.n_subjects} volunteers; anything learned comes from {B.n_calibration} of them and is tested on the other {B.n_validation}. Bed rest with the head tilted down is NASA's standard ground stand-in for weightlessness.</p>
        <div className="tablewrap"><table>
          <thead><tr><th>Transition</th><th className="n">Volunteers</th><th className="n">Plain rolling baseline</th><th className="n">Baseline restarted</th><th className="n">… and band widened</th><th className="n">… and learned shift (pulse-only rule with phase handling)</th></tr></thead>
          <tbody>{Object.keys(B.transitions).map((k) => <tr key={k}><td>{B.labels[k]}</td><td className="n">{tr(k).n}</td><td className="n">{tr(k).naive_flagged}</td><td className="n">{tr(k).reset_flagged}</td><td className="n">{tr(k).reset_widen_flagged}</td><td className="n">{tr(k).aware_flagged}</td></tr>)}</tbody>
        </table></div>
        <p className="small">Number of volunteers flagged, where a flag means {B.flag_rule}. After getting up from weeks in bed the pulse rises, and a plain personal baseline flags {tr('IN_TEST>POST_TEST').naive_flagged} of {tr('IN_TEST>POST_TEST').n} volunteers; the pulse-only rule with phase handling flags {tr('IN_TEST>POST_TEST').aware_flagged}. The fewer flags come from widening the band after a known transition, not from the learned shift, which is only {f2(B.expected_shift_bpm['IN_TEST>POST_TEST'].median, 1)} bpm. With {tr('IN_TEST>POST_TEST').n} volunteers the difference is suggestive, not established (exact paired test p = {f2(tr('IN_TEST>POST_TEST').p_naive_vs_aware)}). Away from transitions, {pct(B.days_outside_transitions.naive.share_of_days_at_or_above_2sd)} of days exceed the same level with a plain baseline and {pct(B.days_outside_transitions.aware.share_of_days_at_or_above_2sd)} with the restarted one, a small cost: nurse-taken pulse is noisy. The flag here is a pulse-only 2-of-3-days rule, not Keel's full detector. Without phase handling the same rule flags {B.luck_14_day_stretches.naive.flagged} of {B.luck_14_day_stretches.naive.stretches} two-week stretches away from any transition ({pct(B.luck_14_day_stretches.naive.share)}): the plain baseline's {tr('IN_TEST>POST_TEST').naive_flagged} of {tr('IN_TEST>POST_TEST').n} is higher but not distinguishable from that (p about 0.1, and the stretches come from few people). For the phase-handling variant, its own chance level with the widened band was not measured, so whether it differs from chance is unknown. Whether the wider band would also hide a real problem after a transition is not tested on real data.</p>
        <p className="figcap"><a href={href('method', 'baseline')}>How phase changes are handled</a> · <code>{B.script}</code></p>
      </Section>

      <Card title="Limits you should know before trusting any of this">
        <ul className="list small">
          <li>No open dataset has astronaut wearable time series. The real evaluation uses people on Earth; spaceflight physiology is represented only by published summary values and the bed-rest analog.</li>
          <li>The real illness data has two indicators. Claims about HRV, oxygen, temperature, mood, reaction time, fluids and food rest on simulation with assumed effect sizes.</li>
          <li>{co.n_events} real episodes is a small sample; intervals are wide. Symptom dates are self-reported and shifted for privacy.</li>
          <li>Thresholds for the full indicator set are calibrated on simulated missions and probably run over budget on real people.</li>
          <li>Detection above luck is likely optimistic about what physiology explains: pretend dates cannot be matched to the calendar, so travel, testing and isolation around a real onset are not reproduced. Heart rate alone ({pts(hr[dep]['1.0'].net_detection)}) is the safer figure.</li>
          <li>The simulator's illness response was fitted on {C.illness.n_events} episode curves from {R.calibration_overlap.calibration_half_people} people; {R.calibration_overlap.their_episodes} of the {co.n_events} evaluated episodes belong to those people, so anything that passes through the simulator (the app's thresholds, the choice of detector) has seen those people; results on the {DC.n_people_held_out} people not used by its fits are given beside the headline (not unseen: the 30% exercise cut and the 30% chance of an unworn night in simulated ground people were set with the real data in view).</li>
          <li>The four personal-baseline detectors perform alike at the notice tier. Keel runs the one picked on simulated training missions by a selection rule that was itself revised during review; the choice has flipped twice, most recently to the simple rule after a sign error in the multivariate statistic was corrected. The simple rule is {pts(R.main.zscore['1.0'].net_detection)} above luck at the notice tier and {pts(R.main.zscore['0.25'].net_detection)} at the alert tier.</li>
        </ul>
        <a className="btn" href={href('method', 'limits')}>Full limitations and what a clinician would need to review</a>
      </Card>
      <p className="tiny muted">Result files, code version: real {R.code_version}, simulated {S.code_version}, realism {Z.code_version}, bed rest {B.code_version}. Scripts: <code>research/scripts/</code>.</p>
    </>
  )
}
